initJs:
function(container, apiUrl, tables) {
  let selectedOrders = new Set();
  let allOrders = [];
  let stores = [];
  let products = [];
  let suppliers = [];

  // 今日の日付を表示
  const today = new Date().toLocaleDateString('ja-JP');
  container.querySelector('#order-date').textContent = today;

  // テーブル再描画関数
  function renderOrderRows(orders) {
    const tbody = container.querySelector('#order-list-tbody');

    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted">発注データがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      const supplier = suppliers.find(s => s.id === order.仕入先ID) || {};
      const statusClass = getStatusClass(order.発注ステータス);
      const isChecked = selectedOrders.has(order.id);
      const isDisabled = order.発注ステータス === '送信済み' || order.発注ステータス === '納品済';

      return `
        <tr data-id="${order.id}">
          <td>
            <input type="checkbox" 
                   class="order-checkbox" 
                   data-id="${order.id}" 
                   ${isChecked ? 'checked' : ''} 
                   ${isDisabled ? 'disabled' : ''} />
          </td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${order.予測数量 || 0}</td>
          <td>${order.発注数量 || 0}</td>
          <td>${supplier.仕入先名 || ''}</td>
          <td>¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td><span class="status-badge ${statusClass}">${order.発注ステータス || '送信待ち'}</span></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  function getStatusClass(status) {
    switch(status) {
      case '送信済み': return 'status-sent';
      case '納品済': return 'status-sent';
      case 'エラー': return 'status-error';
      default: return 'status-pending';
    }
  }

  function updateTotalAmount() {
    const total = allOrders
      .filter(order => selectedOrders.has(order.id))
      .reduce((sum, order) => sum + (order.発注金額 || 0), 0);

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;

    const sendBtn = container.querySelector('#btn-send-selected');
    sendBtn.disabled = selectedOrders.size === 0;
  }

  function showMessage(message, isError = false) {
    const existingMessage = container.querySelector('.error-message, .success-message');
    if (existingMessage) {
      existingMessage.remove();
    }

    const messageDiv = document.createElement('div');
    messageDiv.className = isError ? 'error-message' : 'success-message';
    messageDiv.textContent = message;

    const cardBody = container.querySelector('.card-body');
    cardBody.insertBefore(messageDiv, cardBody.firstChild);

    setTimeout(() => {
      if (messageDiv.parentNode) {
        messageDiv.remove();
      }
    }, 5000);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタ読み込み
      const storeData = await window.aivicApi.list(1);
      if (storeData) {
        stores = storeData.filter(store => store.有効フラグ);
        const storeSelect = container.querySelector('#store-select');
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join('');
      }

      // 商品マスタ読み込み
      const productData = await window.aivicApi.list(2);
      if (productData) {
        products = productData;
      }

      // 発注データ読み込み（今日の日付のもの）
      const orderData = await window.aivicApi.list(7);
      if (orderData) {
        const todayStr = new Date().toISOString().split('T')[0];
        allOrders = orderData.filter(order => {
          const orderDate = new Date(order.発注日).toISOString().split('T')[0];
          return orderDate === todayStr;
        });
      }

      // 仕入先情報を商品マスタから取得（簡易実装）
      suppliers = products.map(product => ({
        id: product.仕入先ID,
        仕入先名: `仕入先${product.仕入先ID?.slice(-4) || '0000'}`
      })).filter((supplier, index, self) => 
        supplier.id && self.findIndex(s => s.id === supplier.id) === index
      );

    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      showMessage('データの読み込みに失敗しました', true);
    }
  }

  // 店舗選択時の処理
  container.querySelector('#store-select').addEventListener('change', async (e) => {
    const storeId = e.target.value;
    selectedOrders.clear();

    if (!storeId) {
      renderOrderRows([]);
      return;
    }

    try {
      const storeOrders = allOrders.filter(order => order.店舗ID === storeId);
      renderOrderRows(storeOrders);
    } catch (error) {
      console.error('店舗別発注データ取得エラー:', error);
      showMessage('発注データの取得に失敗しました', true);
    }
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const isChecked = e.target.checked;
    const storeId = container.querySelector('#store-select').value;

    if (!storeId) return;

    const storeOrders = allOrders.filter(order => 
      order.店舗ID === storeId && 
      order.発注ステータス !== '送信済み' && 
      order.発注ステータス !== '納品済'
    );

    if (isChecked) {
      storeOrders.forEach(order => selectedOrders.add(order.id));
    } else {
      selectedOrders.clear();
    }

    renderOrderRows(storeOrders);
  });

  // 個別チェックボックス
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('order-checkbox')) {
      const orderId = e.target.dataset.id;

      if (e.target.checked) {
        selectedOrders.add(orderId);
      } else {
        selectedOrders.delete(orderId);
      }

      updateTotalAmount();

      // 全選択チェックボックスの状態更新
      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        const storeOrders = allOrders.filter(order => 
          order.店舗ID === storeId && 
          order.発注ステータス !== '送信済み' && 
          order.発注ステータス !== '納品済'
        );
        const allSelected = storeOrders.length > 0 && storeOrders.every(order => selectedOrders.has(order.id));
        container.querySelector('#select-all').checked = allSelected;
      }
    }
  });

  // 送信ボタン
  container.querySelector('#btn-send-selected').addEventListener('click', () => {
    if (selectedOrders.size === 0) {
      showMessage('発注する商品を選択してください', true);
      return;
    }

    // 送信済みデータの重複チェック
    const selectedOrdersData = allOrders.filter(order => selectedOrders.has(order.id));
    const alreadySent = selectedOrdersData.filter(order => 
      order.発注ステータス === '送信済み' || order.発注ステータス === '納品済'
    );

    if (alreadySent.length > 0) {
      showMessage('選択した発注データに送信済みのものが含まれています', true);
      return;
    }

    // 発注数量0の商品チェック
    const zeroQuantityOrders = selectedOrdersData.filter(order => !order.発注数量 || order.発注数量 === 0);
    if (zeroQuantityOrders.length > 0) {
      showMessage('発注数量が0の商品が含まれています。発注数量を確認してください。', true);
      return;
    }

    // 確認ダイアログ表示
    const total = selectedOrdersData.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    container.querySelector('#confirm-message').textContent = 
      `${selectedOrders.size}件の発注データ（合計金額: ¥${total.toLocaleString()}）を送信しますか？`;
    container.querySelector('#send-confirm-dialog').classList.remove('hidden');
  });

  // 確認ダイアログ - 送信実行
  container.querySelector('#confirm-send').addEventListener('click', async () => {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');

    try {
      const selectedOrdersData = allOrders.filter(order => selectedOrders.has(order.id));
      let successCount = 0;
      let errorCount = 0;

      for (const order of selectedOrdersData) {
        try {
          await window.aivicApi.update(7, order.id, {
            ...order,
            発注ステータス: '送信済み',
            更新日時: new Date().toISOString()
          });
          successCount++;
        } catch (error) {
          console.error(`発注ID ${order.id} の送信エラー:`, error);
          await window.aivicApi.update(7, order.id, {
            ...order,
            発注ステータス: 'エラー',
            更新日時: new Date().toISOString()
          });
          errorCount++;
        }
      }

      // データ再読み込み
      const orderData = await window.aivicApi.list(7);
      if (orderData) {
        const todayStr = new Date().toISOString().split('T')[0];
        allOrders = orderData.filter(order => {
          const orderDate = new Date(order.発注日).toISOString().split('T')[0];
          return orderDate === todayStr;
        });
      }

      selectedOrders.clear();

      const storeId = container.querySelector('#store-select').value;
      if (storeId) {
        const storeOrders = allOrders.filter(order => order.店舗ID === storeId);
        renderOrderRows(storeOrders);
      }

      if (errorCount === 0) {
        showMessage(`${successCount}件の発注を正常に送信しました`);
      } else {
        showMessage(`${successCount}件送信成功、${errorCount}件送信失敗`, errorCount > 0);
      }

    } catch (error) {
      console.error('発注送信エラー:', error);
      showMessage('発注送信処理でエラーが発生しました', true);
    }
  });

  // 確認ダイアログ - キャンセル
  container.querySelector('#cancel-send').addEventListener('click', () => {
    container.querySelector('#send-confirm-dialog').classList.add('hidden');
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', async () => {
    try {
      const storeId = container.querySelector('#store-select').value;
      if (!storeId) {
        showMessage('店舗を選択してください', true);
        return;
      }

      const storeOrders = allOrders.filter(order => order.店舗ID === storeId);

      if (storeOrders.length === 0) {
        showMessage('エクスポートするデータがありません', true);
        return;
      }

      const headers = ['商品コード', '商品名', '予測需要数量', '発注数量', '仕入先名', '発注金額', '送信ステータス'];
      const csvData = storeOrders.map(order => {
        const product = products.find(p => p.id === order.商品ID) || {};
        const supplier = suppliers.find(s => s.id === order.仕入先ID) || {};

        return [
          product.商品コード || '',
          product.商品名 || '',
          order.予測数量 || 0,
          order.発注数量 || 0,
          supplier.仕入先名 || '',
          order.発注金額 || 0,
          order.発注ステータス || '送信待ち'
        ];
      });

      const csvContent = '\uFEFF' + [headers, ...csvData]
        .map(row => row.map(cell => `"${cell}"`).join(','))
        .join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `発注送信データ_${today.replace(/\//g, '')}.csv`;
      link.click();

      showMessage('CSVファイルをエクスポートしました');
    } catch (error) {
      console.error('CSVエクスポートエラー:', error);
      showMessage('CSVエクスポートに失敗しました', true);
    }
  });

  // 初期化
  loadInitialData();
}
